/**
 * Which URLs a known oEmbed provider answers for (ADR-042, layer 2).
 *
 * The registry is the oembed.com list, vendored and pinned
 * (`oembed-providers.gen.ts`, regenerated by `pnpm oembed:sync`). A URL that
 * matches a provider's scheme can be asked for its title and thumbnail
 * directly, without fetching the page first. That is one request instead of
 * two, and the only way to get anything from hosts that serve their page to a
 * browser but not to a bot.
 *
 * A scheme is the provider's own pattern, such as `https://*.youtube.com/watch*`.
 * `*` in the host matches only host characters, and `*` in the path matches
 * anything. That distinction is the security of the matcher: the host and the
 * path are matched separately, so a host wildcard can never reach into the
 * path, and `https://evil.example/x.youtube.com/watch` is never taken for
 * YouTube.
 *
 * Pattern: registry. `createOembedRegistry(providers)` takes the data so a test
 * can supply its own.
 */

export interface OembedProvider {
  readonly name: string
  /** The JSON endpoint, with no `url` parameter yet. */
  readonly endpoint: string
  readonly schemes: readonly string[]
}

export interface OembedMatch {
  readonly provider: string
  /** The endpoint with `url` and `format=json` set, ready to fetch. */
  readonly endpointUrl: string
}

export interface OembedRegistry {
  find(url: URL): OembedMatch | null
}

const isHostCharacter = (character: string) => /[a-z0-9.-]/u.test(character)
const isAnyCharacter = () => true

/**
 * Whether `text` matches `pattern`, where `*` stands for any run of characters
 * that `canStar` accepts.
 *
 * This is deliberately not a regular expression. A pattern such as the
 * registry's `https://backtracks.fm/*\/*\/*\/*\/e/*\/*` has six wildcards, and a
 * regex built from it backtracks catastrophically: measured, a URL with 300
 * path segments took a second and a thousand never finished, on a thread that
 * serves every request. This is the standard two-pointer glob match: on a
 * mismatch it returns to the most recent `*` and lets it take one more
 * character, so it never explores a combination twice and costs at most
 * `pattern.length * text.length`.
 */
function globMatch(
  pattern: string,
  text: string,
  canStar: (character: string) => boolean,
): boolean {
  let p = 0
  let t = 0
  let starAt = -1
  let resumeAt = 0
  while (t < text.length) {
    if (pattern[p] === '*') {
      starAt = p
      resumeAt = t
      p += 1
    } else if (p < pattern.length && pattern[p] === text[t]) {
      p += 1
      t += 1
    } else if (starAt !== -1 && canStar(text.charAt(resumeAt))) {
      p = starAt + 1
      resumeAt += 1
      t = resumeAt
    } else {
      return false
    }
  }
  while (pattern[p] === '*') p += 1
  return p === pattern.length
}

interface CompiledScheme {
  readonly host: string
  readonly path: string
}

/** A scheme's host and path, or `null` if it is not an http(s) URL pattern. */
function compileScheme(scheme: string): CompiledScheme | null {
  const rest = scheme.replace(/^https?:\/\//iu, '')
  if (rest === scheme) return null
  const slash = rest.indexOf('/')
  const host = slash === -1 ? rest : rest.slice(0, slash)
  return { host: host.toLowerCase(), path: slash === -1 ? '' : rest.slice(slash) }
}

function endpointFor(endpoint: string, pageUrl: string): string {
  const target = new URL(endpoint)
  target.searchParams.set('url', pageUrl)
  target.searchParams.set('format', 'json')
  return target.href
}

/**
 * Longer than this is not looked up. Real links are far shorter, and a bound
 * on the input is the second half of bounding the match: the first is the
 * algorithm.
 */
const MAX_MATCHED_URL_LENGTH = 4096

interface Candidate {
  readonly provider: OembedProvider
  readonly pattern: CompiledScheme
}

export function createOembedRegistry(providers: readonly OembedProvider[]): OembedRegistry {
  // Most schemes name one host exactly, so they are indexed by it and a lookup
  // tries a handful of patterns, not every pattern of every provider. Only the
  // few with a wildcard in the host are tried for everything.
  const byHost = new Map<string, Candidate[]>()
  const wildcardHosts: Candidate[] = []
  for (const provider of providers) {
    for (const scheme of provider.schemes) {
      const pattern = compileScheme(scheme)
      if (pattern === null) continue
      if (pattern.host.includes('*')) {
        wildcardHosts.push({ provider, pattern })
      } else {
        byHost.set(pattern.host, [...(byHost.get(pattern.host) ?? []), { provider, pattern }])
      }
    }
  }

  return {
    find(url) {
      if (url.href.length > MAX_MATCHED_URL_LENGTH) return null
      // The fragment never reaches the server, so it is not part of a match.
      const path = `${url.pathname}${url.search}`
      const candidates = [...(byHost.get(url.host) ?? []), ...wildcardHosts]
      const hit = candidates.find(
        ({ pattern }) =>
          globMatch(pattern.host, url.host, isHostCharacter) &&
          globMatch(pattern.path, path, isAnyCharacter),
      )
      if (hit === undefined) return null
      return {
        provider: hit.provider.name,
        endpointUrl: endpointFor(hit.provider.endpoint, url.href),
      }
    },
  }
}
